import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Future;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

public class Main {
    public static void main(String[] args) throws Exception {
        demonstrateAdmissionPath();
        demonstrateCallerRunsBackpressure();
        demonstrateExecuteVsSubmitException();
    }

    static void demonstrateAdmissionPath() throws InterruptedException {
        CountDownLatch release = new CountDownLatch(1);
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
                1, 2, 10, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(1),
                namedFactory("admission"),
                new ThreadPoolExecutor.AbortPolicy());
        Runnable blockingTask = () -> {
            try {
                release.await();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };
        pool.execute(blockingTask); // core worker
        pool.execute(blockingTask); // queue
        pool.execute(blockingTask); // non-core worker because queue is full
        boolean rejected = false;
        try {
            pool.execute(blockingTask);
        } catch (RuntimeException expected) {
            rejected = true;
        }
        System.out.println("admission poolSize=" + pool.getPoolSize()
                + ", queue=" + pool.getQueue().size()
                + ", rejected=" + rejected);
        assert pool.getPoolSize() == 2;
        assert pool.getQueue().size() == 1;
        assert rejected;
        release.countDown();
        pool.shutdown();
        pool.awaitTermination(1, TimeUnit.SECONDS);
    }

    static void demonstrateCallerRunsBackpressure() throws InterruptedException {
        CountDownLatch release = new CountDownLatch(1);
        AtomicInteger callerRuns = new AtomicInteger();
        Thread mainThread = Thread.currentThread();
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
                1, 1, 0, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(1),
                namedFactory("caller-runs"),
                new ThreadPoolExecutor.CallerRunsPolicy());
        pool.execute(() -> await(release));
        pool.execute(() -> { });
        pool.execute(() -> {
            if (Thread.currentThread() == mainThread) {
                callerRuns.incrementAndGet();
            }
        });
        System.out.println("callerRuns=" + callerRuns.get());
        assert callerRuns.get() == 1;
        release.countDown();
        pool.shutdown();
        pool.awaitTermination(1, TimeUnit.SECONDS);
    }

    static void demonstrateExecuteVsSubmitException() throws Exception {
        CountDownLatch uncaughtSeen = new CountDownLatch(1);
        AtomicReference<Throwable> uncaught = new AtomicReference<>();
        ThreadFactory factory = runnable -> {
            Thread thread = new Thread(runnable, "exception-demo");
            thread.setUncaughtExceptionHandler((t, e) -> {
                uncaught.set(e);
                uncaughtSeen.countDown();
            });
            return thread;
        };
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
                1, 1, 0, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(1),
                factory,
                new ThreadPoolExecutor.AbortPolicy());
        pool.execute(() -> { throw new IllegalStateException("execute boom"); });
        uncaughtSeen.await(1, TimeUnit.SECONDS);
        System.out.println("execute exception=" + uncaught.get().getMessage());
        assert "execute boom".equals(uncaught.get().getMessage());

        Future<?> future = pool.submit(() -> { throw new IllegalArgumentException("submit boom"); });
        try {
            future.get();
            throw new AssertionError("future.get should expose task failure");
        } catch (ExecutionException expected) {
            System.out.println("submit exception=" + expected.getCause().getMessage());
            assert "submit boom".equals(expected.getCause().getMessage());
        } finally {
            pool.shutdown();
        }
    }

    static ThreadFactory namedFactory(String prefix) {
        AtomicInteger index = new AtomicInteger();
        return runnable -> new Thread(runnable, prefix + "-" + index.incrementAndGet());
    }

    static void await(CountDownLatch latch) {
        try {
            latch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
